#include <iostream>
#include <vector>
#include <array>
#include <algorithm>
using namespace std;

const long long MOD = 1000000007;

long long modPow(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<vector<int>> p(6, vector<int>(6));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            int val;
            cin >> val;
            p[i][j] = (int)((long long)val * modPow(100, MOD - 2) % MOD);
        }
    }

    for (int i = n; i <= 5; ++i) p[i][i] = 1;

    vector<int> combos;
    for (int m = 0; m < 64; ++m) {
        if (bitset<6>(m).count() == 3) {
            combos.push_back(m);
        }
    }

    vector<long long> f(1 << 20), g(1 << 20);

    for (int mask = 0; mask < (1 << 18); ++mask) {
        array<array<bool, 6>, 6> grid;
        grid.fill(false);
        long long prod = 1;
        int bitIdx = 0;

        for (int r = 0; r < 6; ++r) {
            for (int c = 0; c <= 2; ++c) {
                if (mask & (1 << bitIdx)) {
                    grid[r][c] = true;
                    prod = (prod * p[r][c]) % MOD;
                } else {
                    prod = (prod * ((1 - p[r][c] + MOD) % MOD)) % MOD;
                }
                ++bitIdx;
            }
        }

        int combMask = 0;
        for (int i = 0; i < (int)combos.size(); ++i) {
            int combo = combos[i];
            int indices[3];
            int cnt = 0;
            for (int k = 0; k < 6; ++k) {
                if (combo & (1 << k)) indices[cnt++] = k;
            }

            if ((grid[indices[0]][0] && grid[indices[1]][1] && grid[indices[2]][2]) ||
                (grid[indices[0]][0] && grid[indices[2]][1] && grid[indices[1]][2]) ||
                (grid[indices[1]][0] && grid[indices[0]][1] && grid[indices[2]][2]) ||
                (grid[indices[1]][0] && grid[indices[2]][1] && grid[indices[0]][2]) ||
                (grid[indices[2]][0] && grid[indices[0]][1] && grid[indices[1]][2]) ||
                (grid[indices[2]][0] && grid[indices[1]][1] && grid[indices[0]][2])) {
                combMask |= (1 << i);
            }
        }

        f[combMask] = (f[combMask] + prod) % MOD;
    }

    for (int mask = 0; mask < (1 << 18); ++mask) {
        array<array<bool, 6>, 6> grid;
        grid.fill(false);
        long long prod = 1;
        int bitIdx = 0;

        for (int r = 0; r < 6; ++r) {
            for (int c = 3; c <= 5; ++c) {
                if (mask & (1 << bitIdx)) {
                    grid[r][c] = true;
                    prod = (prod * p[r][c]) % MOD;
                } else {
                    prod = (prod * ((1 - p[r][c] + MOD) % MOD)) % MOD;
                }
                ++bitIdx;
            }
        }

        int combMask = 0;
        for (int i = 0; i < (int)combos.size(); ++i) {
            int combo = combos[i];
            int complement = combo ^ 63;
            int indices[3];
            int cnt = 0;
            for (int k = 0; k < 6; ++k) {
                if (complement & (1 << k)) indices[cnt++] = k;
            }

            if ((grid[indices[0]][3] && grid[indices[1]][4] && grid[indices[2]][5]) ||
                (grid[indices[0]][3] && grid[indices[2]][4] && grid[indices[1]][5]) ||
                (grid[indices[1]][3] && grid[indices[0]][4] && grid[indices[2]][5]) ||
                (grid[indices[1]][3] && grid[indices[2]][4] && grid[indices[0]][5]) ||
                (grid[indices[2]][3] && grid[indices[0]][4] && grid[indices[1]][5]) ||
                (grid[indices[2]][3] && grid[indices[1]][4] && grid[indices[0]][5])) {
                combMask |= (1 << i);
            }
        }

        g[combMask] = (g[combMask] + prod) % MOD;
    }

    for (int bit = 0; bit < 20; ++bit) {
        for (int mask = (1 << 20) - 1; mask >= 0; --mask) {
            if (mask & (1 << bit)) {
                g[mask] = (g[mask] + g[mask ^ (1 << bit)]) % MOD;
            }
        }
    }

    long long ans = 0;
    for (int mask = 0; mask < (1 << 20); ++mask) {
        ans = (ans + f[mask] * g[((1 << 20) - 1) ^ mask]) % MOD;
    }

    cout << (1 - ans + MOD) % MOD << '\n';
    return 0;
}
